MIN_RELEVANCE = 0.75


def recall(store, query):
    scored = store.similarity_search_with_relevance_scores(
        query, k=5, score_threshold=MIN_RELEVANCE)
    if not scored:
        return ""
    return "\n".join(doc.page_content for doc, _ in scored)


def build_prompt(store, task):
    memories = recall(store, task)
    return PROMPT.format(memories=memories or "no relevant memory", task=task)
